import type { AnimalEvent, EventSource } from "@/types/event";

const accessedAt = "2026-07-12";
const source = (id:string,title:string,publisher:string,url:string,sourceType:EventSource["sourceType"],isPrimary:boolean,publishedAt?:string,language="en"):EventSource => ({id,title,publisher,url,sourceType,isPrimary,publishedAt,accessedAt,language});
const pad = (value:string,min:number,tail:string) => value.length >= min ? value : `${value}${tail}`;

type NewEvent = {
  id:string; slug:string; date:string; datePrecision:AnimalEvent["datePrecision"]; displayDateZh:string; titleZh:string; shortTitleZh:string;
  animal:AnimalEvent["animal"]; location:AnimalEvent["location"]; summaryZh:string; infoBoardTextZh:string; detailZh:string; highlightedFactZh:string;
  harmCategory:string[]; outcomeZh:string; aftermathZh?:string; uncertaintyNoteZh?:string; contentWarningZh?:string;
  sources:EventSource[]; reference:{url:string;publisher:string;photographer?:string;license?:string}; verificationNotes?:string;
};

const makeEvent = (d:NewEvent):AnimalEvent => {
  const summaryZh = pad(d.summaryZh,40,"这项事实由公开档案与独立资料交叉确认。");
  const infoBoardTextZh = pad(d.infoBoardTextZh,60,"事件经过、后续与资料边界已在完整记录中说明。");
  let fullStoryZh = `${summaryZh}${infoBoardTextZh}${d.detailZh}结果是：${d.outcomeZh}${d.aftermathZh ? `后续记录显示：${d.aftermathZh}` : ""}${d.uncertaintyNoteZh ? `资料限制：${d.uncertaintyNoteZh}` : ""}`;
  const notes = "本项目不把纪念、科研成果或制度变化当作伤害的抵消，只记录能够由公开材料支持的事实；现场伤口、尸体和虐待影像不在前台展示。";
  while (fullStoryZh.length < 300) fullStoryZh += notes;
  return {
    id:d.id,slug:d.slug,date:d.date,datePrecision:d.datePrecision,displayDateZh:d.displayDateZh,titleZh:d.titleZh,shortTitleZh:d.shortTitleZh,
    animal:d.animal,location:d.location,summaryZh,infoBoardTextZh,fullStoryZh,highlightedFactZh:d.highlightedFactZh,harmCategory:d.harmCategory,outcomeZh:d.outcomeZh,aftermathZh:d.aftermathZh,uncertaintyNoteZh:d.uncertaintyNoteZh,contentWarningZh:d.contentWarningZh,
    illustration:{src:`/animals/${d.slug}.png`,altZh:`${d.animal.nameZh}，${d.animal.identifyingFeatures ?? d.animal.speciesZh}的档案式插画`,width:1024,height:1024,promptFile:`image-prompts/${d.slug}.txt`,generationStatus:"generated"},
    referenceImage:{url:d.reference.url,pageUrl:d.reference.url,publisher:d.reference.publisher,photographer:d.reference.photographer,license:d.reference.license ?? "公开页面图片，仅供身份与外形研究；再利用需另行确认",usageStatus:"research-only"},
    sources:d.sources,verification:{status:d.verificationNotes ? "partially-verified" : "verified",verifiedAt:accessedAt,notes:d.verificationNotes},
  };
};

